import sourced from "./tourismSites.json";

// What there is to see in Bénin, and where each fact came from.
//
// The screen used to list five landmarks written from memory. Five is not a
// country, and "everything in Bénin" cannot be recalled — only sourced. So
// this file has two halves, and they are kept apart on purpose:
//
//   - tourismSites.json, regenerated by scripts/fetchTourismSites.js from
//     Wikidata: coordinates, the type, the heritage listing, the French
//     Wikipedia article, and a Commons photograph with its licence and
//     photographer. Nothing in it is typed by hand, so re-running the
//     script cannot quietly lose a correction.
//   - HAND_ENTERED below, for the places Wikidata has nothing usable for.
//     Each one says why it is here rather than there.
//
// What this file does NOT carry: entry prices, opening hours, guide fees
// and telephone numbers. Nothing publishes them in a form worth trusting,
// they change, and a visitor who drives four hours on a stale opening time
// has been failed by the app rather than by the site. The screen says so
// where the design asks for a figure — the same rule the OpenStreetMap
// tier follows on the hotels screen.
import { distanceInKm } from "../utils/geo";
import { compareNames } from "../utils/collate";
import { cities } from "./cities";
import { cityCoordinates } from "./cityCoordinates";
import { nearestKnownCity } from "../utils/nearestCity";

// Places Wikidata cannot supply.
//
// The Route des Pêches is the case that proves the point: it is the thing
// people name second after Ganvié, and its Wikidata item is an empty stub
// — no coordinates, no type, no photograph, not even a country. Typing
// cannot reach it and neither can a photo fetch. So it is written out
// here, with a coordinate that is the road itself rather than a building,
// and no photograph at all rather than a picture of some other beach.
// The coast, which no source here could supply.
//
// Wikidata types almost nothing in Bénin as a beach, and OpenStreetMap has
// exactly ONE named beach in the whole country — Obama Beach, in Cotonou.
// Queried, not assumed. So the Plages chip had a single card on it, and
// that card was the Route des Pêches with no photograph and no
// description: a category that looked broken rather than empty.
//
// Bénin's coast is about 125 km, from the Togo border at Hillacondji to
// the Nigeria border at Kraké, and the stretches below are the ones people
// actually go to. They are written from knowledge rather than fetched, and
// that is worth being plain about: the coordinate is a point on the shore
// rather than an address, good enough to open a map at the right beach and
// not a claim about any particular paillote.
//
// What is NOT written: the names of bars, restaurants and lodges. They
// exist, they change, and this app already has a Restaurants screen listing
// establishments that put themselves there — so every one of these cards
// sends the reader to it rather than to a list nobody here has verified.
const BEACHES = [
  ["hand-beach-fidjrosse", "Plage de Fidjrossè", "Cotonou", 6.3533, 2.3761],
  ["hand-beach-obama", "Obama Beach", "Cotonou", 6.3441, 2.4031],
  ["hand-beach-plm", "Plage PLM Alédjo", "Cotonou", 6.3583, 2.4489],
  ["hand-beach-togbin", "Plage de Togbin", "Abomey-Calavi", 6.3450, 2.3106],
  ["hand-beach-adounko", "Plage d'Adounko", "Abomey-Calavi", 6.3402, 2.2794],
  ["hand-beach-avlekete", "Plage d'Avlékété", "Ouidah", 6.3350, 2.1892],
  ["hand-beach-ouidah", "Plage de Ouidah", "Ouidah", 6.3344, 2.0906],
  ["hand-beach-djegbadji", "Plage de Djègbadji", "Ouidah", 6.3253, 2.0603],
  ["hand-beach-grandpopo", "Plage de Grand-Popo", "Grand-Popo", 6.2783, 1.8283],
  ["hand-beach-agoue", "Plage d'Agoué", "Grand-Popo", 6.2472, 1.7208],
  ["hand-beach-hillacondji", "Plage d'Hillacondji", "Grand-Popo", 6.2422, 1.6231],
  ["hand-beach-djeffa", "Plage de Djeffa", "Sèmè-Podji", 6.3689, 2.5311],
  ["hand-beach-ekpe", "Plage d'Ekpè", "Sèmè-Podji", 6.3808, 2.5539],
  ["hand-beach-seme", "Plage de Sèmè-Kraké", "Sèmè-Podji", 6.3722, 2.6781],
].map(([id, name, admin, latitude, longitude]) => ({
  id,
  name,
  nameEn: name,
  latitude,
  longitude,
  admin,
  types: ["plage"],
  heritage: [],
  article: null,
  photo: null,
  tier: "hand",
  alongKey: "restaurants",
}));

const HAND_ENTERED = [
  ...BEACHES,
  {
    id: "hand-route-des-peches",
    name: "Route des Pêches",
    nameEn: "Route des Pêches",
    // The coast road between Cotonou and Ouidah. The point given is the
    // middle of the stretch, near Avlékété, because a 40 km road has no
    // single address and the nearest end would flatter the drive time.
    latitude: 6.3479,
    longitude: 2.2361,
    admin: "Cotonou — Ouidah",
    types: ["route côtière", "plage"],
    heritage: [],
    article: null,
    photo: null,
    tier: "hand",
    // What is actually along it, said plainly. The bars and restaurants on
    // this road are real and they are also the app's own business: rather
    // than name places nobody here has verified, the card sends the reader
    // to the Restaurants screen, which lists establishments that put
    // themselves there.
    alongKey: "restaurants",
  },
];

// Wikidata's types are precise and there are seventy of them. A reader
// choosing what to do today wants six. The mapping is by word, in the
// order below, because a "palais royal" is history before it is
// architecture and a "réserve de biosphère" is nature before it is a park.
const CATEGORY_RULES = [
  { key: "nature", words: ["parc national", "réserve", "aire protégée", "forêt", "bois sacré", "zone humide", "marécage", "jardin", "parc", "montagne", "massif", "chaîne", "grotte", "lac", "lagune", "fleuve", "rivière", "site Ramsar", "afforestation", "climate"] },
  { key: "beach", words: ["plage", "route côtière"] },
  { key: "heritage", words: ["palais", "site archéologique", "forteresse", "paysage culturel", "patrimoine", "stèle", "navire"] },
  { key: "museum", words: ["musée", "fondation", "centre culturel", "laboratoire", "résidence"] },
  { key: "worship", words: ["cathédrale", "basilique", "mosquée", "temple", "vaudou", "sanctuaire", "pèlerinage", "église"] },
  { key: "memory", words: ["mémorial", "monument", "statue", "sculpture", "fontaine", "place"] },
  { key: "town", words: ["commune", "ville", "établissement humain", "marché", "bâtiment"] },
];

export function categoryOf(site) {
  const types = (site.types ?? []).map((type) => type.toLowerCase());
  for (const rule of CATEGORY_RULES) {
    if (types.some((type) => rule.words.some((word) => type.includes(word)))) {
      return rule.key;
    }
  }
  return "town";
}

// A world heritage site is a different proposition from a listed façade,
// and the badge should not flatten them together.
// What a card says about a place, and in which order it will settle for
// less.
//
// A third of these have no French Wikipedia article — the Palais royaux
// d'Abomey has thirty-nine sitelinks and not one of them is fr — so a
// single source left their cards blank. The order is: the French article,
// then Wikidata's French one-liner, then the English article. English in
// a French app is not ideal; silence about a world heritage site is
// worse, and this only ever shows where the alternative is nothing.
export function siteBlurb(site, language) {
  if (language === "en") {
    return site.summaryEn ?? site.summary ?? site.descriptionFr ?? null;
  }
  return site.summary ?? site.descriptionFr ?? site.summaryEn ?? null;
}

// When there is no sentence anywhere, say what the thing is.
//
// Seventeen of these have no article in either language and no usable
// one-liner — a waterfall at Sosso, the royal palace at Allada, a handful
// of cathedrals and mosques. Their cards showed a name and a drive time
// and nothing else, which reads as a broken card rather than a thin one.
//
// This is not prose and is not dressed as prose: it is the type Wikidata
// records, joined and capitalised, beside the town. "Palais royal ·
// Allada" is a small true thing, and a small true thing beats a gap.
export function siteTypeLine(site) {
  const types = (site.types ?? []).filter(Boolean);
  if (!types.length) return null;
  const first = types[0];
  const label = first.charAt(0).toUpperCase() + first.slice(1);
  return site.city ? `${label} · ${site.city}` : label;
}

// The paragraph, for the screen that has room for one.
//
// siteBlurb returns a sentence because that is what fits on a card. The
// detail page showed the same sentence, so opening a card told you
// nothing you had not already read — which is what "clicking on lac
// Nokoué gives no useful information" was. This returns the article's
// lead where there is one: for the lac Nokoué, its size, the rivers that
// feed it, and the fact that Ganvié sits on its north shore.
export function siteDetail(site, language) {
  if (language === "en") {
    return site.summaryEn ?? site.detail ?? site.summary ?? site.descriptionFr ?? null;
  }
  return site.detail ?? site.summary ?? site.descriptionFr ?? site.summaryEn ?? null;
}

// What else is within reach of a place, which is the question somebody
// standing at one actually has. Straight-line, and sorted, so the answer
// is stable and cheap; the drive is what the list screen bands on.
export function sitesNear(site, count = 4) {
  return tourismSites
    .filter((other) => other.id !== site.id && other.latitude != null)
    .map((other) => ({ ...other, awayKm: distanceInKm(site, other) }))
    .sort((a, b) => a.awayKm - b.awayKm)
    .slice(0, count);
}

export function heritageRank(site) {
  const all = (site.heritage ?? []).join(" ").toLowerCase();
  if (all.includes("patrimoine mondial") && !all.includes("indicative")) return 3;
  if (all.includes("indicative")) return 2;
  if (all.includes("ramsar") || all.includes("biosphère")) return 1;
  return all ? 1 : 0;
}

// Which town a site belongs to, decided the same way for all of them.
//
// Wikidata's P131 is not a town. Across these 124 records it returns a
// commune for some, a department for others — Atacora, Zou, Mono, the
// Collines — nothing at all for nineteen, and for the transboundary parks
// it returns Ghana, Burkina Faso and the Région de la Kara, which is in
// Togo. Filing by that field would put the Parc W in Burkina Faso and
// leave a sixth of the list unfiled.
//
// So the town is computed from the coordinates with the app's own
// nearestKnownCity, over the same 61 towns the picker offers, and P131 is
// used only when it already names one of them. A site more than 120 km
// from any of them keeps no town rather than being assigned a distant one
// — nearestKnownCity's own rule, and the reason the Hôtels screen says
// nothing rather than guessing.
export function cityOf(site) {
  if (site.admin && cityCoordinates[site.admin]) return site.admin;
  return nearestKnownCity(site)?.city ?? null;
}

export const tourismSites = [...sourced, ...HAND_ENTERED]
  .map((site) => ({ ...site, category: categoryOf(site), city: cityOf(site) }))
  .sort((a, b) => compareNames(a.name, b.name));

export const tourismPhotoCount = tourismSites.filter((site) => site.photo).length;

// Distance as the crow flies, which is not a drive time and is not
// presented as one — see the screen, where the band is named in hours by
// road and this only orders the list.
export function withDistance(sites, coords) {
  if (!coords) return sites.map((site) => ({ ...site, distanceKm: null }));
  return sites.map((site) => ({
    ...site,
    distanceKm: distanceInKm(coords, site),
  }));
}

// How long it takes to get there, and why that is a band and not a number.
//
// The design's organising idea is "how long have you got", which only works
// if a site's distance is expressed in driving hours from where the reader
// actually is: the Pendjari is a nine-hour expedition from Cotonou and a
// morning out from Natitingou, and one list cannot describe both.
//
// The hours come from the design document's own origin×region matrix. They
// are estimates by road and are labelled as such on screen — a road here
// is not a constant, and the state of the pistes in the north changes what
// the same distance costs. What is NOT done is dressing a straight-line
// distance up as a drive time, which would be precise and wrong: 130 km of
// coast road and 130 km of Atacora track are not the same afternoon.
// Every town the app knows, not six.
//
// The document ships a matrix of driving hours from six departure towns to
// eight regions, and a picker offering six towns is a picker that does not
// offer yours. The matrix is still what this is calibrated against — it is
// somebody's real knowledge of these roads — but it is fitted rather than
// copied:
//
//   hours = 0.6 + km / 59
//
// Least squares over all 48 of the document's cells, RMS 0.49 h. Against
// its own figures from Cotonou: Abomey 2.5 → 2.3, the Atacora 8 → 8.3, the
// Alibori 10 → 9.6. Half an hour out on an eight-hour drive, and the
// screen only uses it to choose between a half day, a day and a weekend —
// a band that survives that error.
//
// What it buys is that any point works: all 61 towns the app holds
// coordinates for, and the phone's own position if that is ever wired in.
// The 0.6 h is the part that is not distance — getting out of a town, the
// ferry, the diversion.
const ROAD_BASE_HOURS = 0.6;
const ROAD_KM_PER_HOUR = 59;

export const tourismOrigins = cities
  .filter((name) => cityCoordinates[name])
  .map((name) => ({
    key: name,
    label: name,
    latitude: cityCoordinates[name].latitude,
    longitude: cityCoordinates[name].longitude,
  }))
  .sort((a, b) => compareNames(a.label, b.label));

export function driveHours(site, originKey) {
  const origin = tourismOrigins.find((item) => item.key === originKey);
  if (!origin || site.latitude == null) return null;
  return ROAD_BASE_HOURS + distanceInKm(origin, site) / ROAD_KM_PER_HOUR;
}

// Under an hour is an afternoon, up to three is a day, beyond that is a
// weekend. The thresholds are the design's.
export const tourismBands = [
  // Asked for in exactly these words: "it must show stuff classified by
  // cities". The document's three bands answer "how long have you got",
  // which is a good question and not the only one — somebody in Porto-Novo
  // looking for Porto-Novo does not want the Musée Honmè filed under "1 to
  // 3 hours" because it happens to be an hour from Cotonou. So the town
  // comes first and the travel bands widen from there.
  { key: "ville", maxHours: 0 },
  { key: "proche", maxHours: 1 },
  { key: "journee", maxHours: 3 },
  { key: "weekend", maxHours: Infinity },
];

export function bandOf(hours) {
  if (hours == null) return null;
  if (hours < 1) return "proche";
  if (hours <= 3) return "journee";
  return "weekend";
}
